package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string          // PIC X(2) @0 len=2
	BrAcct   string          // PIC X(4) @2 len=4
	BrType   string          // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "   // PIC X(2) len=2 = SPACES
var WsPrevAcct string = "    " // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal = decimal.New(0, -2)
var WsBranchTot decimal.Decimal = decimal.New(0, -2)
var WsGrandTot decimal.Decimal = decimal.New(0, -2)
var WsSkipped int64 = 0
var WsAmtEd string // PIC ZZ,ZZ9.99 len=9
var WsBalEd string // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var ledgerRec LedgerRec
var ledgerLines []string
var ledgerIdx int
var atEnd bool

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func truncToPIC(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	if val.IsZero() {
		return decimal.New(0, -scale)
	}
	modulus := decimal.New(1, int32(intDigits)+scale)
	scaled := val.Shift(scale).Truncate(0)
	sign := 1
	if scaled.Sign() < 0 {
		sign = -1
		scaled = scaled.Abs()
	}
	q := scaled.Div(modulus).Truncate(0)
	rem := scaled.Sub(q.Mul(modulus))
	if sign < 0 {
		rem = rem.Neg()
	}
	return rem.Shift(-scale)
}
func truncBal(v decimal.Decimal) decimal.Decimal { return truncToPIC(v, 7, 2) }
func truncBranch(v decimal.Decimal) decimal.Decimal { return truncToPIC(v, 9, 2) }
func truncGrand(v decimal.Decimal) decimal.Decimal { return truncToPIC(v, 9, 2) }

func formatEdited(val decimal.Decimal, pic string) string {
	hasSign := len(pic) > 0 && pic[0] == '-'
	picBody := pic
	signChar := ' '
	if hasSign {
		picBody = pic[1:]
		if val.Sign() < 0 && !val.IsZero() {
			signChar = '-'
		} else {
			signChar = ' '
		}
	}
	dotIdx := strings.Index(picBody, ".")
	intPic := picBody[:dotIdx]
	fracPic := picBody[dotIdx+1:]
	fracDigits := len(fracPic)

	// count integer digit slots
	capacity := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			capacity++
		}
	}
	// absolute scaled value
	absVal := val.Abs()
	scaled := absVal.Shift(2).Truncate(0) // 2 fractional digits
	// integer part truncated to capacity (high-order drop)
	// scaled = int*100+frac ; modulus 10^(capacity+2) already applied by truncToPIC before formatting,
	// but we also apply high-order drop for values that exceed capacity directly (same as truncToPIC)
	// To handle overflow for display, do mod on scaled
	modPow := capacity + fracDigits
	var intPartVal decimal.Decimal
	var fracStr string
	if modPow > 0 {
		modulus := decimal.New(1, int32(modPow))
		// if scaled >= modulus, keep low order digits
		if scaled.Cmp(modulus) >= 0 {
			q := scaled.Div(modulus).Truncate(0)
			scaled = scaled.Sub(q.Mul(modulus))
		}
	}
	// extract integer and fraction
	fracMod := decimal.New(1, int32(fracDigits))
	q := scaled.Div(fracMod).Truncate(0)
	fracDec := scaled.Sub(q.Mul(fracMod))
	intInt := q.IntPart() // fits in int64 because capacity <=9
	// build digitStr zero padded to capacity
	digitStr := fmt.Sprintf("%0*d", capacity, intInt)
	// frac string zero padded
	fracInt := fracDec.IntPart()
	fracStr = fmt.Sprintf("%0*d", fracDigits, fracInt)

	// build integer part
	intChars := []rune(intPic)
	outInt := make([]rune, len(intChars))
	digitIdx := 0
	suppress := true
	for i, ch := range intChars {
		if ch == ',' {
			if suppress {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		} else if ch == 'Z' || ch == '9' {
			d := rune(digitStr[digitIdx])
			digitIdx++
			if ch == 'Z' && suppress && d == '0' {
				// check if this is effectively leading zero: need to see if any non-zero remains?
				// but rule: suppress while d==0 and ch==Z
				// However if all remaining digits are zero and only Z's left until final 9, we keep suppressing
				outInt[i] = ' '
				// suppress stays true
			} else {
				outInt[i] = d
				suppress = false
			}
		} else {
			outInt[i] = ch
		}
	}
	body := string(outInt) + "." + fracStr
	if hasSign {
		return string(signChar) + body
	}
	return body
}

func READ_PARA() {
	if ledgerIdx >= len(ledgerLines) {
		WsEofFlag = "Y"
		return
	}
	line := ledgerLines[ledgerIdx]
	ledgerIdx++
	// pad to 14
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	ledgerRec.BrBranch = line[0:2]
	ledgerRec.BrAcct = line[2:6]
	ledgerRec.BrType = line[6:7]
	amtStr := line[7:14]
	amtStrTrim := strings.TrimSpace(amtStr)
	var n int64 = 0
	if amtStrTrim != "" {
		// amtStr should be digits; parse
		var parsed int64
		// allow any non-digit -> treat as 0 for that char? but spec says digits only
		// just parse if all digits
		allDigits := true
		for _, c := range amtStrTrim {
			if c < '0' || c > '9' {
				allDigits = false
				break
			}
		}
		if allDigits {
			fmt.Sscan(amtStrTrim, &parsed)
			n = parsed
		} else {
			// fallback: extract digits
			var b strings.Builder
			for _, c := range amtStr {
				if c >= '0' && c <= '9' {
					b.WriteRune(c)
				}
			}
			s := b.String()
			if s != "" {
				fmt.Sscan(s, &parsed)
				n = parsed
			}
		}
	}
	ledgerRec.BrAmt = decimal.New(n, -2)
}

func PROCESS_PARA() {
	if isFirstRecord() {
		WsPrevBranch = ledgerRec.BrBranch
		WsPrevAcct = ledgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if ledgerRec.BrBranch != WsPrevBranch {
			ACCT_BREAK_PARA()
			BRANCH_BREAK_PARA()
			WsPrevBranch = ledgerRec.BrBranch
			WsPrevAcct = ledgerRec.BrAcct
		} else {
			if ledgerRec.BrAcct != WsPrevAcct {
				ACCT_BREAK_PARA()
				WsPrevAcct = ledgerRec.BrAcct
			}
		}
	}
	POST_PARA()
	READ_PARA()
}

func POST_PARA() {
	WsAmtEd = formatEdited(ledgerRec.BrAmt, "ZZ,ZZ9.99")
	switch ledgerRec.BrType {
	case "D":
		WsBal = truncBal(WsBal.Add(ledgerRec.BrAmt))
		displayConcat(ledgerRec.BrAcct, " D ", WsAmtEd)
	case "C":
		WsBal = truncBal(WsBal.Sub(ledgerRec.BrAmt))
		displayConcat(ledgerRec.BrAcct, " C ", WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		displayConcat(ledgerRec.BrAcct, " ? SKIPPED")
	}
}

func ACCT_BREAK_PARA() {
	WsBalEd = formatEdited(WsBal, "-Z,ZZZ,ZZ9.99")
	displayConcat("  ACCOUNT ", WsPrevAcct, " BALANCE:", WsBalEd)
	WsBranchTot = truncBranch(WsBranchTot.Add(WsBal))
	WsBal = decimal.New(0, -2)
}

func BRANCH_BREAK_PARA() {
	WsTotEd = formatEdited(WsBranchTot, "-ZZZ,ZZZ,ZZ9.99")
	displayConcat(" BRANCH ", WsPrevBranch, " TOTAL:", WsTotEd)
	WsGrandTot = truncGrand(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.New(0, -2)
}

func GRAND_PARA() {
	WsTotEd = formatEdited(WsGrandTot, "-ZZZ,ZZZ,ZZ9.99")
	displayConcat("GRAND TOTAL:", WsTotEd)
	skippedStr := fmt.Sprintf("%02d", WsSkipped)
	displayConcat("SKIPPED: ", skippedStr)
}

func displayConcat(parts ...string) {
	var b strings.Builder
	for _, p := range parts {
		b.WriteString(p)
	}
	b.WriteString("\n")
	os.Stdout.WriteString(b.String())
}

func main() {
	// open input.dat as LINE SEQUENTIAL
	f, err := os.Open("input.dat")
	if err == nil {
		sc := bufio.NewScanner(f)
		// allow long lines
		buf := make([]byte, 0, 64*1024)
		sc.Buffer(buf, 10*1024*1024)
		for sc.Scan() {
			ledgerLines = append(ledgerLines, sc.Text())
		}
		f.Close()
	} else {
		ledgerLines = []string{}
	}
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevBranch = strings.Repeat(" ", 2)
	WsPrevAcct = strings.Repeat(" ", 4)
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	if !isFirstRecord() {
		ACCT_BREAK_PARA()
		BRANCH_BREAK_PARA()
	}
	// CLOSE LEDGER-FILE (no file to write)
	GRAND_PARA()
}

